const cfg = $('CONFIG - thèmes et chaîne').first().json;
const historique = $('REGROUPER HISTORIQUE').first().json.historique || [];

const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const anneeDepuisDate=value=>{
  const m=String(value||'').trim().match(/^(\d{4})/);
  return m ? Number(m[1]) : null;
};
const dateAdmissible=value=>{
  const y=anneeDepuisDate(value);
  return y===null || y>=1990;
};

const nomsDecesConnus=new Set(['guy bourde','eric duhamel']);

// Retraitement explicite uniquement avant validation ou création d'un brouillon.
// La règle 1990 s'applique aussi aux dossiers A_RETRAITER.
const retryRows=historique.filter(r=>
  String(r.statut||'').trim().toUpperCase()==='A_RETRAITER' &&
  !String(r.draft_id||'').trim() &&
  String(r.validation_contact||'').trim().toUpperCase()!=='OUI' &&
  String(r.validation_contact||'').trim().toUpperCase()!=='OUI_EXCEPTION' &&
  !String(r.email_contact||'').trim() &&
  dateAdmissible(r.date_publication) &&
  !nomsDecesConnus.has(norm(r.auteur))
);
const retry=new Set(retryRows.map(r=>String(r.cle_unique||'').trim()));

// Livres déjà enregistrés : ne pas les traiter deux fois.
const existants = new Set(
  historique
    .filter(r=>!retry.has(String(r.cle_unique||'').trim()))
    .map(r => String(r.cle_unique || '').trim())
    .filter(Boolean)
);

// Auteurs à ne pas contacter / à ne pas reprospecter tant que le doute décès n'est pas levé.
const banned = new Set(
  historique
    .filter(r =>
      ['NE_PAS_CONTACTER','REFUSE','OPPOSITION','BLOQUE_ELIGIBILITE','A_VERIFIER_DECES'].includes(
        String(r.statut || '').trim().toUpperCase()
      )
    )
    .map(r => norm(r.auteur))
    .filter(Boolean)
);
for(const n of nomsDecesConnus)banned.add(n);

// Réutiliser les données enregistrées sans dépendre du classement Google Books.
if(retryRows.length){
 const seen=new Set();
 const records=retryRows.filter(r=>{
  const key=String(r.cle_unique||'').trim();
  const author=String(r.auteur||'').trim();
  if(!key || !author || !String(r.livre||'').trim() || seen.has(key) || banned.has(norm(author)))return false;
  seen.add(key);return true;
 }).slice(0,20).map(r=>({json:{
  cle_unique:String(r.cle_unique).trim(),auteur:String(r.auteur).trim(),livre:String(r.livre).trim(),
  editeur:String(r.editeur||''),date_publication:String(r.date_publication||''),
  description_livre:String(r.description_livre||'').slice(0,1600),source_livre:String(r.source_livre||''),
  sous_titre:String(r.sous_titre||''),langue:String(r.langue||'à vérifier à partir du titre et de la description'),categories:[],
  chaine:String(r.chaine||cfg.chaine),statut:'A_VERIFIER',validation_contact:'NON'
 },pairedItem:{item:0}}));
 if(records.length)return records;
 // Si les A_RETRAITER sont devenus inadmissibles (date < 1990, décès, fiche incomplète),
 // on continue vers une recherche neuve au lieu de bloquer toute l'exécution.
}

const livres = $input.all().flatMap((page,pageIndex)=> {
 if(page.json.error) throw new Error('Google Books a renvoyé une erreur : vérifier le nœud HTTP.');
 return (page.json.items || []).map(b=>({b,pageIndex}));
});

const candidats = [];
const institution=/\b(library|bibliotheque|association|society|societe|congress|congres|committee|comite|university|universite|institute|institut|ministere|department|collectif|anonymous|anonyme)\b/;
const catalogue=/^(revue|bulletin|almanach|catalogue|bibliographie|bibliography|finding lists|ibss)\b/;
const vus = new Set();
const max = 20;

for (const {b,pageIndex} of livres) {
  const v = b.volumeInfo || {};
  const cle = String(b.id || '').trim();
  const auteur = String((v.authors || [])[0] || '').trim();
  const livre = String(v.title || '').trim();
  const editeur = String(v.publisher || '').trim();
  const date = String(v.publishedDate || '').trim();

  // RÈGLE V16 : tout ouvrage dont l'année connue est antérieure à 1990 est rejeté immédiatement.
  // Une date absente ou non exploitable ne suffit pas à rejeter le livre.
  if(!dateAdmissible(date)) continue;

  if(String(v.language||'').toLowerCase()!=='fr' || institution.test(norm(auteur)) || catalogue.test(norm(livre))) continue;

  if (
    !cle || !auteur || !livre ||
    existants.has(cle) || vus.has(cle) ||
    banned.has(norm(auteur))
  ) continue;

  vus.add(cle);

  candidats.push({
    json: {
      cle_unique: cle,
      auteur,
      livre,
      sous_titre: String(v.subtitle||''),
      langue: String(v.language||''),
      categories: v.categories||[],
      editeur,
      date_publication: date,
      description_livre: String(v.description || '').replace(/<[^>]*>/g, ' ').slice(0, 1600),
      source_livre: String(v.infoLink || 'https://books.google.com/'),
      chaine: cfg.chaine,
      statut: 'A_VERIFIER',
      validation_contact: 'NON'
    },
    pairedItem: { item: pageIndex }
  });

  if (candidats.length >= max) break;
}

if (!candidats.length) throw new Error(
 'Aucun nouveau livre exploitable : livres antérieurs à 1990, doublons, langue non française, auteurs bloqués, institutions, catalogues ou fiches incomplètes. Modifiez la recherche dans CONFIG ; conservez votre historique.'
);
return candidats;

const recherches=$input.all();
return recherches.map((item,i)=>{
 const livre=$('VALIDER CONTROLE DECES PRECOCE').itemMatching(i).json;
 const web=item.json.web?.results||[];
 const resultats=web.slice(0,10).map(r=>({
   titre:r.title||'',url:r.url||'',description:r.description||'',origine:'auteur_general'
 }));
 return {json:{...livre,resultats_auteur:resultats},pairedItem:{item:i}};
});

function signalDeces(value) {
 const s=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g, '')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g, '')
  .replace(/\babsence de mention de deces\b/g, '')
  .replace(/\bpas de mention de deces\b/g, '');
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary|necrologie)\b/.test(s);
}
const genericLocal=/^(presse|press|media|medias|communication|communications|contact|info|servicepresse|relationspresse|rp|marketing|publicite|publicity|editorial|edition|editions|auteur|auteurs|author|authors)$/;
const recherches = $input.all();

return recherches.map((item, i) => {
  const livre = item.json;
  const resultats_editeur = livre.resultats_editeur || [];
  const sources = [...(livre.resultats_auteur || []), ...resultats_editeur];

  const emails = [];
  const vus = new Set();
  const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const auteurNorm=norm(livre.auteur);
  const auteurNom=(auteurNorm.split(/\s+/).filter(Boolean).pop()||'');
  const editeurNorm=norm(livre.editeur).replace(/\b(editions?|publishing|publishers?|press|books)\b/g,' ').replace(/\s+/g,' ').trim();

  for (const r of sources) {
    const contexte=norm((r.titre||'')+' '+(r.description||'')+' '+(r.url||''));
    if(!((auteurNorm.length>5 && contexte.includes(auteurNorm)) ||
         (auteurNom.length>3 && contexte.includes(auteurNom)) ||
         (editeurNorm.length>3 && contexte.includes(editeurNorm)))) continue;
    if(!/^https:\/\//i.test(String(r.url||''))) continue;

    const description = String(r.description || '');
    const url = String(r.url || '');
    const texteContact = description.replace(/<[^>]*>/g,'')
      .replace(/&#64;|&#x40;|&commat;/gi,'@')
      .replace(/\s*\[(?:at|arobase)\]\s*|\s*\((?:at|arobase)\)\s*/gi,'@')
      .replace(/\s*\[(?:dot|point)\]\s*/gi,'.');

    for (const m of texteContact.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)) {
      const email=m[0].toLowerCase();
      if(/^(orders?|support|customer|international_cs|noreply|no-reply|sales)@/i.test(email)) continue;
      const cle=email+'|'+url;
      if(vus.has(cle)) continue;
      vus.add(cle);

      const local=email.split('@')[0].replace(/[._-]/g,'');
      const generique=genericLocal.test(local);
      const auteurDansContexte=(auteurNorm.length>5&&contexte.includes(auteurNorm))||(auteurNom.length>3&&contexte.includes(auteurNom));
      let categorie='AUTRE_CONTACT_PRO';
      if(!generique && auteurDansContexte) categorie='AUTEUR_DIRECT';
      else if(generique && /presse|press|media|communication|relations/.test(local+' '+contexte)) categorie='PRESSE_GENERIQUE';
      else if(generique) categorie='EDITEUR_GENERIQUE';
      else if(editeurNorm.length>3&&contexte.includes(editeurNorm)) categorie='EDITEUR_CONTACT';

      const priorite=categorie==='AUTEUR_DIRECT'?1:(categorie==='EDITEUR_CONTACT'?2:(categorie==='PRESSE_GENERIQUE'?3:4));
      emails.push({email,source:url,extrait:description,verification:'NON',categorie_contact:categorie,priorite,origine:r.origine||''});
    }
  }
  emails.sort((a,b)=>a.priorite-b.priorite || a.email.localeCompare(b.email));

  const urls_candidats=[...new Set(sources.map(r=>String(r.url||'')).filter(url=>/^https:\/\//i.test(url)))].slice(0,50);
  const signalSources=sources.some(r=>signalDeces((r.titre||'')+' '+(r.description||'')));

  return {json:{
    ...livre,
    signal_deces:Boolean(livre.signal_deces_precoce)||signalSources||signalDeces(livre.description_livre),
    resultats_editeur,
    candidats_email:emails,
    urls_candidats,
    recherches_auteur:JSON.stringify(livre.resultats_auteur||[]),
    recherches_editeur:JSON.stringify(resultats_editeur),
    emails_candidats:JSON.stringify(emails),
    sources_contacts:JSON.stringify(urls_candidats),
    source_contact_validee:'',
    email_contact:'',
    type_contact:'',
    validation_contact:'NON',
    statut:'A_VERIFIER',
    draft_id:''
  },pairedItem:{item:i}};
});

const FOOTER="Pour vous donner une idée du format, voici un exemple d’interview que j’ai réalisée sur ma chaîne consacrée à l’Afrique :\n\nhttps://www.youtube.com/watch?v=z9B8b6ZrCb4";
function signalDeces(value) {
 const s=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g, '')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g, '')
  .replace(/\babsence de mention de deces\b/g, '')
  .replace(/\bpas de mention de deces\b/g, '');
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary|necrologie)\b/.test(s);
}
const known=new Set(['guy bourde','eric duhamel']);
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();

return $input.all().map((item,i)=>{
 const base=$('CONSTRUIRE DOSSIER SOURCES').itemMatching(i).json;
 const alertes=[];
 alertes.push('SELECTION_EDITORIALE : '+String(base.raison_selection||''));
 if(base.controle_deces_raison) alertes.push('CONTROLE_DECES_PRECOCE : '+String(base.controle_deces_raison));
 if(!String(base.editeur||'').trim()) alertes.push('EDITEUR_A_IDENTIFIER : consulter les recherches éditeur et renseigner le nom vérifié avant toute création de brouillon destiné à un éditeur.');

 let data={};
 let bloque=Boolean(base.signal_deces || base.signal_deces_precoce || known.has(norm(base.auteur)));
 let erreur=false;

 if(bloque) {
   alertes.push('BLOCAGE_DECES : signal de décès ou auteur explicitement bloqué. Aucune invitation produite.');
 } else {
  try {
   const texte=(item.json.content||[]).filter(b=>b.type==='text'||typeof b.text==='string').map(b=>b.text||'').join('\n').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
   if(item.json.stop_reason==='max_tokens')throw Error('réponse tronquée');
   data=JSON.parse(texte);
   if(!data||Array.isArray(data)||typeof data!=='object')throw Error('objet attendu');
  } catch(e) {
   erreur=true;alertes.push('BLOCAGE_FORMAT : réponse Claude invalide.');
  }

  // IMPORTANT V16 : les alertes Claude sont ajoutées AVANT le garde-fou décès.
  if(Array.isArray(data.informations_a_verifier)) alertes.push(...data.informations_a_verifier.map(String));
  else {erreur=true;alertes.push('BLOCAGE_FORMAT : liste des alertes absente.');}

  if(data.invitation_possible!==true || signalDeces(JSON.stringify(alertes))) {
   bloque=true;
   alertes.push('BLOCAGE_ELIGIBILITE : invitation non autorisée ou signal biographique à vérifier.');
  }
 }

 const champs=['objet_auteur','message_auteur','objet_editeur','message_editeur'];
 const sortie={};
 for(const cle of champs){
  let texte=typeof data[cle]==='string'?data[cle].trim():'';
  if(!bloque && (!texte || texte.length>10000)){erreur=true;alertes.push('BLOCAGE_TEXTE : champ vide ou trop long '+cle);}
  if(cle.startsWith('objet') && /[\r\n]/.test(texte)){erreur=true;alertes.push('BLOCAGE_TEXTE : objet multiligne.');}
  if(cle.startsWith('message') && texte && !bloque) {
   texte=texte.replace(/\bune telle échange\b/gi,'un tel échange');
   texte=texte.replace(/\bj['’]ai lu votre synthèse\b/gi,'Je m’intéresse à votre synthèse');
   texte=texte.replace(/\bje solicite\b/gi,'je sollicite');
   if(/\bj['’]ai (?:lu|relu|dévoré)|\baprès (?:avoir lu|lecture de)|\bayant lu\b/i.test(texte)) {
    erreur=true;alertes.push('BLOCAGE_TEXTE : affirmation de lecture non fournie dans '+cle);
   }
   texte=texte.replace(/\bUn échange ([^.!?\n]+?) nous intéresserait vivement\./g,'Je serais vivement intéressé par un échange $1.');
   texte=texte.replace(/\bnous indiquer\b/gi,'m’indiquer');
   texte=texte.replace(/\bde nos cadres constitutionnels\b/gi,'des cadres constitutionnels français');
   texte=texte.replace(/\bnos cadres constitutionnels\b/gi,'les cadres constitutionnels français');
   if(/https?:\/\//i.test(texte)){erreur=true;alertes.push('BLOCAGE_TEXTE : lien non autorisé dans '+cle);}
   const style=texte.match(/assistant éditorial|équipe éditoriale|\bnous\b|\bnotre\s+(?:chaîne|chaine|équipe|equipe|média|media|plateforme)\b|\bnos\s+(?:émissions|emissions|vidéos|videos)\b/gi);
   if(style)alertes.push('STYLE_A_RELIRE : '+cle+' contient '+[...new Set(style)].join(', ')+'. Vérifier le contexte et privilégier une rédaction au nom de Walid.');
   texte=texte.replace(/\n+(?:Cordialement|Bien cordialement|Bien à vous|Avec mes salutations)[\s\S]*$/i,'').trim();
   texte=texte.replace(/\n+(?:Walid\s*\n+)?Impacteur (?:Afrique|Frexit)\s*$/i,'').trim();
   sortie[cle]=texte+'\n\n'+FOOTER+'\n\nCordialement,\nWalid\n'+base.chaine;
  } else sortie[cle]=texte;
 }
 if(!['Impacteur Afrique','Impacteur Frexit'].includes(base.chaine)){erreur=true;alertes.push('BLOCAGE_CHAINE : chaîne inconnue.');}

 // Dernier filet indépendant de l'invitation générée.
 const deathCorpus=[
   base.description_livre,base.recherches_auteur,base.recherches_editeur,
   JSON.stringify(alertes),base.controle_deces_raison
 ].join('\n');
 if(signalDeces(deathCorpus) || known.has(norm(base.auteur))){
   bloque=true;
   alertes.push('BLOCAGE_FINAL_DECES : garde-fou déterministe V16 déclenché.');
 }

 if(bloque||erreur) for(const cle of champs)sortie[cle]='';
 alertes.push('CONTROLE_V16 : contrôle automatique effectué, validation humaine de l’identité, des faits, du texte et du contact requise.');

 return {json:{
  cle_unique:base.cle_unique,auteur:base.auteur,livre:base.livre,editeur:base.editeur,
  date_publication:base.date_publication,source_livre:base.source_livre,description_livre:base.description_livre,chaine:base.chaine,
  recherches_auteur:JSON.stringify(base.resultats_auteur||[]),recherches_editeur:JSON.stringify(base.resultats_editeur||[]),
  emails_candidats:JSON.stringify(base.candidats_email||[]),sources_contacts:JSON.stringify(base.urls_candidats||[]),
  ...sortie,informations_a_verifier:JSON.stringify(alertes),
  email_contact:'',type_contact:'',source_contact_validee:'',validation_contact:'NON',
  statut:bloque?'BLOQUE_ELIGIBILITE':erreur?'A_CORRIGER':'A_VERIFIER',draft_id:'',
  derniere_mise_a_jour:new Date().toISOString()
 },pairedItem:{item:i}};
});

function signalDeces(value) {
 const s=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g,'')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g,'')
  .replace(/\babsence de mention de deces\b/g,'')
  .replace(/\bpas de mention de deces\b/g,'');
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary|necrologie)\b/.test(s);
}
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const known=new Set(['guy bourde','eric duhamel']);
const publicDomains=new Set(['gmail.com','hotmail.com','outlook.com','yahoo.com','proton.me','icloud.com','live.com']);

const lignes=$input.all().map(i=>i.json);
const pasContacterEmails=new Set(lignes.filter(r=>['NE_PAS_CONTACTER','REFUSE','OPPOSITION'].includes(String(r.statut||'').trim().toUpperCase())).map(r=>String(r.email_contact||'').trim().toLowerCase()).filter(Boolean));
const pasContacterAuteurs=new Set(lignes.filter(r=>['NE_PAS_CONTACTER','REFUSE','OPPOSITION','BLOQUE_ELIGIBILITE','A_VERIFIER_DECES'].includes(String(r.statut||'').trim().toUpperCase())).map(r=>norm(r.auteur)).filter(Boolean));
for(const n of known)pasContacterAuteurs.add(n);

const cleContact=r=>JSON.stringify([String(r.cle_unique||'').trim(),String(r.email_contact||'').trim().toLowerCase()]);
const dejaTraites=new Set(lignes.filter(r=>String(r.draft_id||'').trim()||['BROUILLON_CREE','ENVOYE','REPONSE_RECUE'].includes(String(r.statut||'').trim().toUpperCase())).map(cleContact));
const sortie=[];const selection=new Set();

for(let i=0;i<lignes.length;i++){
 const r={...lignes[i]};
 const alertes=String(r.informations_a_verifier||'');
 const auteurNorm=norm(r.auteur);
 if(known.has(auteurNorm)||pasContacterAuteurs.has(auteurNorm))continue;
 if(!(alertes.includes('CONTROLE_V16')||alertes.includes('CONTROLE_V6')) || /BLOCAGE_/.test(alertes) ||
    signalDeces([r.recherches_auteur,r.description_livre,alertes].join('\n')))continue;

 const statut=String(r.statut||'').trim().toUpperCase();
 const email=String(r.email_contact||'').trim().toLowerCase();
 const type=String(r.type_contact||'').trim().toLowerCase();
 const validation=String(r.validation_contact||'').trim().toUpperCase();

 if(!['Impacteur Afrique','Impacteur Frexit'].includes(String(r.chaine||'').trim()))continue;
 r.chaine=String(r.chaine).trim();

 const exception=validation==='OUI_EXCEPTION';
 const approuve=validation==='OUI'||exception;
 const src=String(r.source_contact_validee||'').trim();
 const typesAuteur=new Set(['auteur','auteur_direct']);
 const typesEditeur=new Set(['editeur','presse_generique','service_presse']);

 if(statut!=='APPROUVE'||!approuve||!/^https:\/\//i.test(src)||!/^\S+@\S+\.\S+$/.test(email)||
    (!typesAuteur.has(type)&&!typesEditeur.has(type))||r.draft_id||dejaTraites.has(cleContact(r))||
    pasContacterEmails.has(email)||selection.has(cleContact(r)))continue;

 const domain=email.split('@')[1]||'';
 if(publicDomains.has(domain)&&!exception)continue;
 if(typesEditeur.has(type)&&!String(r.editeur||'').trim())continue;

 const isAuteur=typesAuteur.has(type);
 const objet=String(r[isAuteur?'objet_auteur':'objet_editeur']||'').trim();
 const message=String(r[isAuteur?'message_auteur':'message_editeur']||'').trim();
 if(!objet||!message||!r.cle_unique)continue;
 if(!message.endsWith('Cordialement,\nWalid\n'+r.chaine) ||
    message.split("https://www.youtube.com/watch?v=z9B8b6ZrCb4").length!==2 ||
    !message.includes("Pour vous donner une idée du format, voici un exemple d’interview que j’ai réalisée sur ma chaîne consacrée à l’Afrique :\n\nhttps://www.youtube.com/watch?v=z9B8b6ZrCb4"))continue;

 selection.add(cleContact(r));
 sortie.push({json:{cle_unique:r.cle_unique,email_contact:email,chaine:r.chaine,objet,message,type_contact:type},pairedItem:{item:i}});
 if(sortie.length>=3)break;
}
return sortie;

